python - '$(inputs.rnafold.path)' final.txt <<'PY'
import re, sys
with open(sys.argv[1]) as handle:
    lines = [line.strip() for line in handle if line.strip()]
if len(lines) != 3 or lines[0] != ">URS0000668495":
    raise SystemExit("Unexpected RNAfold record")
seq = lines[1]
m = re.fullmatch(r"([().]+)\s+\(\s*(-?\d+(?:\.\d+)?)\)", lines[2])
if not m:
    raise SystemExit("Invalid RNAfold structure/energy line")
structure, energy = m.groups()
if len(seq) != len(structure):
    raise SystemExit("Sequence and structure lengths differ")
balance = 0
for char in structure:
    if char == "(":
        balance += 1
    elif char == ")":
        balance -= 1
        if balance < 0:
            raise SystemExit("Unbalanced dot-bracket structure")
if balance:
    raise SystemExit("Unbalanced dot-bracket structure")
answer = structure + "," + f"{float(energy):.2f}"
if not re.fullmatch(r"[().]+,-?\d+\.\d{2}", answer):
    raise SystemExit("Final formatting check failed")
with open(sys.argv[2], "w") as out:
    out.write(answer + "\n")
PY

